<script setup lang="ts">
import {ref,computed,watch} from 'vue';import TraceView from '../components/TraceView.vue';import SchedulePlayback from '../components/SchedulePlayback.vue';import {api,type Trace,type Simulation,type Question,type Grade,type Execution,type Schema} from '../api';import {useLab} from '../store';import SqlEditor from '../components/SqlEditor.vue';import ResultTable from '../components/ResultTable.vue';
const editor=ref<InstanceType<typeof SqlEditor>>();
const props=defineProps<{theme:string}>();const lab=useLab();const selected=ref('where');const hint=ref(false);const solution=ref(false);const onlyMistakes=ref(false);const grading=ref<Grade>();const trial=ref<Execution>();const process=ref<{kind:string,trace?:Trace,simulation?:Simulation,source?:string}>();const fixtureSchema=ref<Schema>(lab.schema);const question=computed(()=>lab.questions.find(q=>q.id===selected.value));const key=computed(()=>`${selected.value}@${lab.workspace?.exercise_seed??0}`);const answer=computed({get:()=>lab.workspace?.exercise_answers[key.value]??question.value?.starter??'',set:(v:string)=>{lab.workspace!.exercise_answers[key.value]=v;lab.touch();grading.value=undefined;trial.value=undefined;process.value=undefined;}});const chapters=computed(()=>[...new Set(lab.questions.map(q=>q.chapter))]);
watch(()=>lab.revision,()=>{process.value=undefined});
watch(question,async q=>{lab.touch();hint.value=false;solution.value=false;grading.value=undefined;trial.value=undefined;process.value=undefined;if(q){try{const schema=await api<Schema>('fixture_schema',{fixture:q.fixture});if(q===question.value)fixtureSchema.value=schema}catch(e){lab.fail(e)}}},{immediate:true});
async function grade(){if(!question.value)return;const r=await lab.run<Grade>('grade','grade',{id:question.value.id,answer:answer.value,seed:lab.workspace!.exercise_seed,engine:question.value.engine});if(r){grading.value=r;lab.workspace!.progress[key.value]=r.status;if(r.status==='failed'&&!lab.workspace!.mistakes.includes(key.value)){lab.workspace!.mistakes.push(key.value);lab.workspace!.mistakes=lab.workspace!.mistakes.slice(-500);}lab.dirty=true;lab.log(r.message)}}
async function visualize(){process.value=undefined;if(!question.value)return;await editor.value?.source(true);const r=await lab.run<{kind:string,trace?:Trace,simulation?:Simulation,source?:string}>('exercise-trace','exercise_trace',{id:question.value.id,answer:answer.value,seed:lab.workspace!.exercise_seed});if(r)process.value=r;}
async function run(){if(!question.value)return;if(question.value.engine==='mysql'){await grade();return;}const r=await lab.run<Execution>('trial','exercise_run',{id:question.value.id,answer:answer.value,seed:lab.workspace!.exercise_seed,engine:question.value.engine});if(r)trial.value=r;}
async function reseed(){lab.touch();lab.questions=await api<Question[]>('catalog',{seed:lab.workspace!.exercise_seed});grading.value=undefined;}
function reset(){delete lab.workspace!.exercise_answers[key.value];delete lab.workspace!.progress[key.value];grading.value=undefined;trial.value=undefined;process.value=undefined;lab.touch();}
const differences=computed(()=>{const expected=grading.value?.expected?.rows??[],actual=grading.value?.actual?.rows??[];const remaining=new Map<string,number[]>();actual.forEach((row,i)=>{const k=JSON.stringify(row);remaining.set(k,[...(remaining.get(k)??[]),i])});const missing:number[]=[];expected.forEach((row,i)=>{const list=remaining.get(JSON.stringify(row));if(list?.length)list.shift();else missing.push(i)});return question.value?.ordered?{expected:expected.flatMap((row,i)=>JSON.stringify(row)===JSON.stringify(actual[i])?[]:[i]),actual:actual.flatMap((row,i)=>JSON.stringify(row)===JSON.stringify(expected[i])?[]:[i])}:{expected:missing,actual:[...remaining.values()].flat()};});
const visible=(q:Question)=>!onlyMistakes.value||lab.workspace!.mistakes.some(k=>k.startsWith(`${q.id}@`));
</script>
<template><div class="exercise-page"><aside class="course-tree"><div class="sidebar-title">HNU DATABASE COURSE</div><label class="check"><input v-model="onlyMistakes" type="checkbox">只看错题</label><details v-for="chapter in chapters" :key="chapter" open><summary>{{String(chapter).padStart(2,'0')}} {{lab.questions.find(q=>q.chapter===chapter)?.chapter_title}}</summary><button v-for="q in lab.questions.filter(q=>q.chapter===chapter&&visible(q))" :key="q.id" :class="{active:selected===q.id}" @click="selected=q.id"><span :class="lab.workspace?.progress[`${q.id}@${lab.workspace.exercise_seed}`]==='passed'?'success':'muted'">{{lab.workspace?.progress[`${q.id}@${lab.workspace.exercise_seed}`]==='passed'?'✓':'○'}}</span>{{q.title}}</button></details></aside><section v-if="question" class="exercise-work"><header class="page-heading"><div><span class="eyebrow">CHALLENGE {{question.chapter}} · {{question.engine.toUpperCase()}}</span><h1>{{question.title}}</h1></div><div class="seed"><label>随机种子<input v-model.number="lab.workspace!.exercise_seed" type="number" min="0" max="4294967295" @change="reseed"></label></div></header><p class="question-prompt">{{question.prompt}}</p><div class="source-note">依据：{{question.source}} · {{question.pages}}<br>公开数据：{{question.fixture}}；运行与判题使用隔离数据库，不改变你的工作区。</div><div class="exercise-actions"><button class="primary" data-testid="grade" :disabled="!!lab.jobs.grade" @click="grade">✓ 提交判题</button><button v-if="['query','mutation','schema','routine'].includes(question.kind)" :disabled="!!lab.jobs.trial" @click="run">▶ 试运行</button><button v-if="['query','algebra','schedule'].includes(question.kind)" data-testid="exercise-trace" @click="visualize">逐步演示</button><button @click="hint=!hint">提示</button><button @click="solution=!solution">{{solution?'收起解析':'查看解析'}}</button><button @click="reset">重新作答</button></div><div v-if="hint" class="notice">{{question.hint}}</div><div class="answer-editor"><SqlEditor ref="editor" :id="`exercise-${key}`" v-model="answer" :schema="fixtureSchema" :engine="question.engine" :language="['concept','schedule'].includes(question.kind)?'json':question.kind==='algebra'?'plaintext':'sql'" :theme="props.theme" @run="grade"/></div><TraceView v-if="process?.trace" :trace="process.trace" @highlight="editor?.highlight($event)"/><SchedulePlayback v-if="process?.simulation" :result="process.simulation" :source="process.source??''"/><div v-if="grading" class="grade-card" :class="grading.status"><strong>{{grading.status==='passed'?'✓ 测试通过':grading.status==='failed'?'需要再试一次':'判定未完成'}}</strong><p>{{grading.message}}</p><small>{{grading.explanation}}</small><ResultTable v-if="grading.expected" :table="grading.expected" :diff-rows="differences.expected" title="失败数据组的期望结果" compact/><ResultTable v-if="grading.actual" :table="grading.actual" :diff-rows="differences.actual" title="你的结果" compact/></div><div v-if="trial"><div v-if="trial.error" class="notice warning">{{trial.error}}</div><ResultTable v-for="(r,i) in trial.results" :key="i" :table="r.table" :title="`试运行 ${i+1} · ${r.affected} 行受影响`"/></div><section v-if="solution" class="solution"><h3>参考答案与解析</h3><pre>{{question.solution}}</pre><p>{{question.explanation}}</p><button @click="answer=question.solution">填入参考答案</button></section></section></div></template>
